import React from 'react';

export default function KeyPointsSection({ originalText, keyPoints, setKeyPoints }) {
  // Placeholder: implement API call to backend for key points extraction
  return (
    <div>
      <h2 className="font-bold mb-2">Key Points</h2>
      <ul className="list-disc pl-6 bg-white p-2 rounded border min-h-[6rem]">
        {keyPoints.length === 0 ? (
          <li className="text-gray-500">(Key points will appear here)</li>
        ) : (
          keyPoints.map((point, idx) => <li key={idx}>{point}</li>)
        )}
      </ul>
    </div>
  );
}
